package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_27_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        String input = "1.23E3"; // Scientific notation
        try {
            Number result = NumberUtils.createNumber(input);
            assertTrue("Expected a Double instance", result instanceof Double);
            assertEquals("Expected value 1230.0", 1230.0, result.doubleValue(), 0.0);
        } catch (NumberFormatException e) {
            fail("NumberFormatException was not expected for input: " + input);
        }
    }
}

